LANDMARK_TRUTH_X = 5.0

def build_lying_graph(weight_mode: str, rep_for_liar: float | None) -> PoseGraph:
    """3 honest peers report range=5 (truth); 1 liar reports range=10.
    Mirrors `_make_lying_landmark_graph` in tests/eval/test_baselines.py.

    NOTE: for switchable mode, build with weight_mode="exogenous" first,
    register every factor with `add_switch()`, THEN flip the mode — SC
    can't be combined with GNC's outer loop (it has its own outlier
    mechanism)."""
    pg = PoseGraph()
    pg.set_weight_mode(weight_mode if weight_mode != "switchable" else "exogenous")
    pg.add_pose("p0", Pose2(0.0, 0.0, 0.0))
    pg.add_landmark("lm0", (4.0, 0.0))
    info = landmark_information(5.0)
    for i in range(3):
        lf = LandmarkFactor("p0", "lm0", 5.0, 0.0, info, f"honest_{i}")
        pg.add_landmark_factor(lf)
        if rep_for_liar is not None:
            pg.set_reputation_weight(lf, 1.0)
    liar = LandmarkFactor("p0", "lm0", 10.0, 0.0, landmark_information(10.0), "liar")
    pg.add_landmark_factor(liar)
    if rep_for_liar is not None:
        pg.set_reputation_weight(liar, rep_for_liar)
    if weight_mode == "switchable":
        for factor in pg._landmark_factors:
            pg.add_switch(factor, prior_strength=1.0)
        pg.set_weight_mode("switchable")
    return pg

def solve_mode(weight_mode: str, rep_for_liar: float | None) -> float:
    pg = build_lying_graph(weight_mode, rep_for_liar)
    if weight_mode == "switchable":
        pg.optimize()  # SC competes with GNC — use plain LM
    else:
        pg.optimize_gnc()
    return pg.landmarks()["lm0"][0]

results: dict[str, float] = {}
for mode, rep in [("gnc", None), ("dcs", None), ("switchable", None), ("exogenous", 0.9)]:
    results[mode] = solve_mode(mode, rep)

print("mode          landmark_x   |err vs truth|")
for mode, x in results.items():
    print(f"  {mode:12s} {x:8.4f}     {abs(x - LANDMARK_TRUTH_X):.4f} m")
